class Command(BaseCommand):
    help = 'Carga el catalogo completo de 55 logros de forma idempotente.'

    def handle(self, *args, **kwargs):
        self.stdout.write('Cargando logros...')
        
        creadas = 0
        actualizadas = 0

        for item in LOGROS_DATA:
            fields = item['fields']
            nombre = fields['nombre']

            defaults = {
                'descripcion': fields.get('descripcion', ''),
                'tipo': fields.get('tipo', 'insignia'),
                'categoria': fields.get('categoria', 'general'),
                'dificultad': fields.get('dificultad', 'facil'),
                'puntos': fields.get('puntos', 10),
                'requisito': fields.get('requisito', ''),
                'es_secreto': fields.get('es_secreto', False),
                'activo': fields.get('activo', True),
            }

            obj, created = Logro.objects.get_or_create(
                nombre=nombre,
                defaults=defaults
            )

            if not created:
                for k, v in defaults.items():
                    setattr(obj, k, v)
                obj.save()
                actualizadas += 1
            else:
                creadas += 1

        self.stdout.write(self.style.SUCCESS(f'[OK] Logros cargados: {creadas} creadas, {actualizadas} actualizadas.'))
